#pragma once
// Exact scalar IPv6 forwarding-atlas, packed image, and cache-budgeted planner.
#include <algorithm>
#include <array>
#include <cassert>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <deque>
#include <limits>
#include <map>
#include <queue>
#include <stdexcept>
#include <string>
#include <unordered_map>
#include <utility>
#include <vector>

using Key = unsigned __int128;
using i128 = __int128;

static const i128 INF_WORK = ((i128)1) << 120;

inline std::string hexkey(Key x) {
    static const char *d = "0123456789abcdef";
    std::string s(32, '0');
    for (int i = 31; i >= 0; --i) {
        s[i] = d[(unsigned)(x & 15)];
        x >>= 4;
    }
    return s;
}

inline Key key(const std::string &s) {
    if (s.size() != 32) throw std::runtime_error("key width");
    Key v = 0;
    for (char c : s) {
        int d;
        if (c >= '0' && c <= '9') d = c - '0';
        else if (c >= 'a' && c <= 'f') d = c - 'a' + 10;
        else if (c >= 'A' && c <= 'F') d = c - 'A' + 10;
        else throw std::runtime_error("key digit");
        v = (v << 4) | (unsigned)d;
    }
    return v;
}

inline std::string decimal128(i128 v) {
    if (v == 0) return "0";
    bool neg = v < 0;
    unsigned __int128 u = neg ? (unsigned __int128)(-(v + 1)) + 1 : (unsigned __int128)v;
    std::string s;
    while (u) {
        s.push_back((char)('0' + (int)(u % 10)));
        u /= 10;
    }
    if (neg) s.push_back('-');
    std::reverse(s.begin(), s.end());
    return s;
}

// ---------------------------------------------------------------- utilities
inline uint16_t rd16(const std::vector<uint8_t> &v, size_t o) {
    return (uint16_t)v[o] | ((uint16_t)v[o + 1] << 8);
}
inline uint32_t rd32(const std::vector<uint8_t> &v, size_t o) {
    return (uint32_t)v[o] | ((uint32_t)v[o + 1] << 8) |
           ((uint32_t)v[o + 2] << 16) | ((uint32_t)v[o + 3] << 24);
}
inline void wr16(std::vector<uint8_t> &v, size_t o, uint16_t x) {
    v[o] = (uint8_t)x;
    v[o + 1] = (uint8_t)(x >> 8);
}
inline void wr32(std::vector<uint8_t> &v, size_t o, uint32_t x) {
    v[o] = (uint8_t)x;
    v[o + 1] = (uint8_t)(x >> 8);
    v[o + 2] = (uint8_t)(x >> 16);
    v[o + 3] = (uint8_t)(x >> 24);
}
inline Key rdkey(const std::vector<uint8_t> &v, size_t o, int width) {
    Key x = 0;
    for (int i = width - 1; i >= 0; --i) x = (x << 8) | v[o + (size_t)i];
    return x;
}
inline void wrkey(std::vector<uint8_t> &v, size_t o, Key x, int width) {
    for (int i = 0; i < width; ++i) {
        v[o + (size_t)i] = (uint8_t)x;
        x >>= 8;
    }
}

inline std::vector<uint8_t> from_hex(const std::string &s) {
    auto digit = [](char c) -> int {
        if (c >= '0' && c <= '9') return c - '0';
        if (c >= 'a' && c <= 'f') return c - 'a' + 10;
        if (c >= 'A' && c <= 'F') return c - 'A' + 10;
        return -1;
    };
    if (s.size() & 1) throw std::runtime_error("hex width");
    std::vector<uint8_t> out(s.size() / 2);
    for (size_t i = 0; i < out.size(); ++i) {
        int a = digit(s[2 * i]), b = digit(s[2 * i + 1]);
        if (a < 0 || b < 0) throw std::runtime_error("hex digit");
        out[i] = (uint8_t)((a << 4) | b);
    }
    return out;
}

inline std::string to_hex(const std::vector<uint8_t> &v) {
    static const char *d = "0123456789abcdef";
    std::string s;
    s.resize(v.size() * 2);
    for (size_t i = 0; i < v.size(); ++i) {
        s[2 * i] = d[v[i] >> 4];
        s[2 * i + 1] = d[v[i] & 15];
    }
    return s;
}

// ------------------------------------------------------------------- ATLAS
struct AtlasRoute {
    Key start;
    int length;
    int hop;
};

struct AtlasEvent {
    Key x;
    int type;  // 0 = end, 1 = start; ends sort before starts at one boundary
    int length;
    int hop;
};

// Return maximal contiguous LPM runs. Null is represented by hop -1.
inline std::vector<std::pair<Key, int>> build_atlas(const std::vector<AtlasRoute> &fib) {
    std::vector<AtlasEvent> ev;
    ev.reserve(fib.size() * 2);
    for (const auto &r : fib) {
        ev.push_back({r.start, 1, r.length, r.hop});
        if (r.length > 0) {
            Key step = (Key)1 << (128 - r.length);
            Key end = r.start + step;  // U wraps to zero
            if (end != 0) ev.push_back({end, 0, r.length, r.hop});
        }
    }
    std::sort(ev.begin(), ev.end(), [](const AtlasEvent &a, const AtlasEvent &b) {
        if (a.x != b.x) return a.x < b.x;
        if (a.type != b.type) return a.type < b.type;
        if (a.length != b.length) return a.length < b.length;
        return a.hop < b.hop;
    });

    std::map<int, int> active;  // prefix length -> hop, active chain only
    std::vector<std::pair<Key, int>> runs;
    auto lpm = [&]() -> int {
        if (active.empty()) return -1;
        return active.rbegin()->second;
    };
    auto emit = [&](Key start, int hop) {
        if (!runs.empty() && runs.back().second == hop) return;
        runs.push_back({start, hop});
    };

    Key prev = 0;
    size_t i = 0;
    while (i < ev.size()) {
        Key x = ev[i].x;
        if (x > prev) emit(prev, lpm());
        // All events at x are one half-open boundary.  Ends have type 0.
        while (i < ev.size() && ev[i].x == x) {
            if (ev[i].type == 0) {
                active.erase(ev[i].length);
            } else {
                active[ev[i].length] = ev[i].hop;
            }
            ++i;
        }
        prev = x;
    }
    // The final interval always extends conceptually to U=2^128.
    emit(prev, lpm());
    return runs;
}

// ------------------------------------------------------------ image records
struct Layout {
    int lo = 0;
    int span = 0;
    int mode = 0;
    int cached = 0;
    std::vector<int> children;  // empty means leaf
};

inline int mode_width(int mode) {
    static const int w[3] = {16, 8, 4};
    return w[mode];
}
inline int mode_lanes(int mode) {
    static const int lanes[3] = {4, 8, 16};
    return lanes[mode];
}

// b == 0 means a leaf; otherwise b is the number of internal children.
inline int payload_key_count(int span, int b) {
    return b == 0 ? span : b - 1;
}

inline int node_used_bytes(int span, int b, int mode) {
    int k = payload_key_count(span, b);
    return 32 + 4 * b + k * mode_width(mode);
}

inline int node_alloc_bytes(int span, int b, int mode) {
    int used = node_used_bytes(span, b, mode);
    return ((used + 63) / 64) * 64;
}

inline int node_pages(int span, int b, int mode) {
    return node_alloc_bytes(span, b, mode) / 64;
}

struct TreeAnswer {
    int hop = -1;
    int run = 0;
    std::vector<unsigned> path;
};

inline std::vector<uint8_t> build_image_bytes(const std::vector<Key> &starts,
                                              const std::vector<int> &hops,
                                              const std::vector<Layout> &nodes) {
    const int R = (int)starts.size();
    const int N = (int)nodes.size();
    if (R < 1 || N < 1) throw std::runtime_error("empty image");
    std::vector<int> alloc(N), off(N);
    size_t cursor = 64;
    for (int i = 0; i < N; ++i) {
        int b = (int)nodes[i].children.size();
        alloc[i] = node_alloc_bytes(nodes[i].span, b, nodes[i].mode);
        off[i] = (int)cursor;
        cursor += (size_t)alloc[i];
    }
    size_t hopoff = cursor;
    size_t hopbytes = (((size_t)R * 4 + 63) / 64) * 64;
    size_t total = hopoff + hopbytes;
    std::vector<uint8_t> img(total, 0);
    img[0] = 'F'; img[1] = 'I'; img[2] = 'D'; img[3] = 'X';
    img[4] = 2; img[5] = img[6] = img[7] = 0;
    wr32(img, 8, (uint32_t)R);
    wr32(img, 12, (uint32_t)N);
    wr32(img, 16, (uint32_t)hopoff);
    wr32(img, 20, (uint32_t)total);
    // bytes 24..63 are already zero

    for (int i = 0; i < N; ++i) {
        const Layout &nd = nodes[i];
        int b = (int)nd.children.size();
        int kind = b == 0 ? 1 : 0;
        int k = payload_key_count(nd.span, b);
        int width = mode_width(nd.mode);
        size_t o = (size_t)off[i];
        img[o] = (uint8_t)kind;
        img[o + 1] = (uint8_t)nd.mode;
        img[o + 2] = (uint8_t)nd.cached;
        img[o + 3] = 0;
        wr16(img, o + 4, (uint16_t)nd.lo);
        wr16(img, o + 6, (uint16_t)nd.span);
        wr16(img, o + 8, (uint16_t)(b == 0 ? nd.span : b));
        wr16(img, o + 10, 0);
        wr32(img, o + 12, (uint32_t)alloc[i]);
        Key base = starts[nd.lo];
        wrkey(img, o + 16, base, 16);
        size_t p = o + 32;
        if (b != 0) {
            for (int c = 0; c < b; ++c) {
                wr32(img, p, (uint32_t)off[nd.children[c]]);
                p += 4;
            }
            for (int c = 1; c < b; ++c) {
                Key absolute = starts[nodes[nd.children[c]].lo];
                Key stored = nd.mode == 0 ? absolute : absolute - base;
                wrkey(img, p, stored, width);
                p += (size_t)width;
            }
        } else {
            for (int r = nd.lo; r < nd.lo + nd.span; ++r) {
                Key absolute = starts[r];
                Key stored = nd.mode == 0 ? absolute : absolute - base;
                wrkey(img, p, stored, width);
                p += (size_t)width;
            }
        }
        assert((int)(p - o) == node_used_bytes(nd.span, b, nd.mode));
        (void)k;
    }

    for (int r = 0; r < R; ++r) {
        uint32_t x = hops[r] < 0 ? 0xffffffffu : (uint32_t)hops[r];
        wr32(img, hopoff + (size_t)4 * r, x);
    }
    return img;
}

struct ImageNode {
    int kind = 0;
    int mode = 0;
    int lo = 0;
    int span = 0;
    int count = 0;
    std::vector<uint32_t> children;
    std::vector<Key> keys;  // absolute
};

// Parse a complete FIDX v2 image and perform lookups using only its bytes.
inline std::vector<TreeAnswer> trace_image_bytes(const std::vector<uint8_t> &img,
                                                 const std::vector<Key> &addresses) {
    if (img.size() < 128 || img.size() % 64 != 0 ||
        std::memcmp(img.data(), "FIDX", 4) != 0 || img[4] != 2)
        throw std::runtime_error("bad image");
    uint32_t R = rd32(img, 8);
    uint32_t N = rd32(img, 12);
    uint32_t hopoff = rd32(img, 16);
    uint32_t total = rd32(img, 20);
    if (total != img.size() || hopoff % 64 != 0 || hopoff > total)
        throw std::runtime_error("bad image header");

    std::map<uint32_t, ImageNode> nodes;
    size_t off = 64;
    for (uint32_t n = 0; n < N; ++n) {
        if (off + 32 > hopoff) throw std::runtime_error("truncated node");
        ImageNode nd;
        nd.kind = img[off];
        nd.mode = img[off + 1];
        nd.lo = rd16(img, off + 4);
        nd.span = rd16(img, off + 6);
        nd.count = rd16(img, off + 8);
        uint32_t allocated = rd32(img, off + 12);
        Key base = rdkey(img, off + 16, 16);
        size_t p = off + 32;
        int key_count;
        if (nd.kind == 0) {
            int b = nd.count;
            key_count = b - 1;
            for (int c = 0; c < b; ++c) {
                nd.children.push_back(rd32(img, p));
                p += 4;
            }
        } else {
            key_count = nd.span;
        }
        int width = mode_width(nd.mode);
        for (int k = 0; k < key_count; ++k) {
            Key raw = rdkey(img, p, width);
            p += (size_t)width;
            nd.keys.push_back(nd.mode == 0 ? raw : base + raw);
        }
        nodes[(uint32_t)off] = std::move(nd);
        off += allocated;
        if (off > hopoff) throw std::runtime_error("node overrun");
    }
    if (off != hopoff) throw std::runtime_error("node/hop gap");

    std::vector<TreeAnswer> out;
    out.reserve(addresses.size());
    for (Key address : addresses) {
        TreeAnswer ans;
        uint32_t o = 64;
        while (true) {
            ans.path.push_back(o);
            auto it = nodes.find(o);
            if (it == nodes.end()) throw std::runtime_error("bad child offset");
            const ImageNode &nd = it->second;
            if (nd.kind == 1) {
                auto upper = std::upper_bound(nd.keys.begin(), nd.keys.end(), address);
                if (upper == nd.keys.begin()) throw std::runtime_error("leaf predecessor");
                int rel = (int)(upper - nd.keys.begin()) - 1;
                ans.run = nd.lo + rel;
                if (ans.run < 0 || (uint32_t)ans.run >= R) throw std::runtime_error("run range");
                uint32_t h = rd32(img, hopoff + (size_t)4 * (uint32_t)ans.run);
                ans.hop = h == 0xffffffffu ? -1 : (int)h;
                break;
            } else {
                auto upper = std::upper_bound(nd.keys.begin(), nd.keys.end(), address);
                int c = (int)(upper - nd.keys.begin());  // equality goes right
                if (c < 0 || c >= (int)nd.children.size()) throw std::runtime_error("child index");
                o = nd.children[(size_t)c];
            }
        }
        out.push_back(std::move(ans));
    }
    return out;
}

// -------------------------------------------------------- exact planner data
struct CostModel {
    int hit = 1;
    int miss = 1;
    int decode[3] = {0, 0, 0};
};

struct PlanVersionInput {
    std::vector<Key> starts;
    std::vector<int> hops;
};

struct PlanBurstInput {
    int version = 0;
    long long repeat = 1;
    std::vector<Key> addresses;
};

struct RunStats {
    int R = 0;
    std::vector<i128> Q;  // (R+1)*(R+1), only i<j used
    std::vector<i128> T;
    inline i128 q(int i, int j) const { return Q[(size_t)i * (R + 1) + j]; }
    inline i128 t(int i, int j) const { return T[(size_t)i * (R + 1) + j]; }
};

inline RunStats make_run_stats(const std::vector<Key> &starts,
                               const std::vector<int> &hops,
                               const std::vector<PlanBurstInput> &bursts,
                               const std::vector<int> &burst_ids) {
    (void)hops;
    const int R = (int)starts.size();
    RunStats st;
    st.R = R;
    st.Q.assign((size_t)(R + 1) * (R + 1), 0);
    st.T.assign((size_t)(R + 1) * (R + 1), 0);
    std::vector<i128> qrun(R, 0);
    std::vector<int> pref(R + 1);
    for (int bi : burst_ids) {
        const PlanBurstInput &burst = bursts[(size_t)bi];
        std::vector<unsigned char> touched(R, 0);
        for (Key a : burst.addresses) {
            auto it = std::upper_bound(starts.begin(), starts.end(), a);
            if (it == starts.begin()) throw std::runtime_error("address before atlas");
            int r = (int)(it - starts.begin()) - 1;
            qrun[(size_t)r] += (i128)burst.repeat;
            touched[(size_t)r] = 1;
        }
        pref[0] = 0;
        for (int r = 0; r < R; ++r) pref[r + 1] = pref[r] + (touched[(size_t)r] ? 1 : 0);
        for (int i = 0; i < R; ++i) {
            for (int j = i + 1; j <= R; ++j) {
                if (pref[j] - pref[i] > 0)
                    st.T[(size_t)i * (R + 1) + j] += (i128)burst.repeat;
            }
        }
    }
    std::vector<i128> qpref(R + 1, 0);
    for (int r = 0; r < R; ++r) qpref[r + 1] = qpref[r] + qrun[(size_t)r];
    for (int i = 0; i < R; ++i) {
        for (int j = i + 1; j <= R; ++j)
            st.Q[(size_t)i * (R + 1) + j] = qpref[j] - qpref[i];
    }
    return st;
}

inline bool mode_legal(const std::vector<Key> &starts, int i, int j, int mode) {
    if (mode == 0) return true;
    Key spread = starts[(size_t)j - 1] - starts[(size_t)i];
    if (mode == 1) return spread < ((Key)1 << 64);
    return spread < ((Key)1 << 32);
}

struct DPEntry {
    i128 work = INF_WORK;
    int pages = 0;
    uint8_t kind = 0;   // 0 unreachable, 1 leaf, 2 internal
    uint8_t mode = 0;
    uint8_t cached = 0;
    uint8_t b = 0;      // children for internal, zero for leaf
};

struct AuxEntry {
    i128 work = INF_WORK;
    int pages = 0;
    uint16_t split = 0;
    uint8_t leftq = 0;
    uint8_t valid = 0;
};

struct OptTables {
    int R = 0;
    int C = 0;
    std::vector<DPEntry> dp;
    std::vector<AuxEntry> aux;

    OptTables() = default;
    OptTables(int r, int c) : R(r), C(c) {
        dp.resize((size_t)(R + 1) * (R + 1) * (C + 1));
        aux.resize((size_t)R * 10 * (R + 1) * (C + 1));
    }
    inline DPEntry &d(int i, int j, int q) {
        return dp[((size_t)i * (R + 1) + j) * (C + 1) + q];
    }
    inline const DPEntry &d(int i, int j, int q) const {
        return dp[((size_t)i * (R + 1) + j) * (C + 1) + q];
    }
    inline AuxEntry &a(int i, int b, int j, int q) {
        return aux[(((size_t)i * 10 + b) * (R + 1) + j) * (C + 1) + q];
    }
    inline const AuxEntry &a(int i, int b, int j, int q) const {
        return aux[(((size_t)i * 10 + b) * (R + 1) + j) * (C + 1) + q];
    }
};

inline bool better_pair(i128 w, int p, i128 ow, int op) {
    return w < ow || (w == ow && p < op);
}

inline void optimize_version(OptTables &tab, const std::vector<Key> &starts,
                             const std::vector<int> &hops,
                             const std::vector<PlanBurstInput> &bursts,
                             const std::vector<int> &burst_ids,
                             const CostModel &cost) {
    const int R = tab.R;
    const int C = tab.C;
    (void)hops;
    RunStats st = make_run_stats(starts, hops, bursts, burst_ids);

    for (int span = 1; span <= R; ++span) {
        for (int i = 0; i + span <= R; ++i) {
            const int j = i + span;
            const int maxb = std::min(9, span);

            // Auxiliary segmentation states: [i,j) partitioned into b child subtrees.
            for (int b = 2; b <= maxb; ++b) {
                for (int k = i + b - 1; k <= j - 1; ++k) {
                    const DPEntry *right_base = &tab.d(k, j, 0);
                    (void)right_base;
                    for (int ql = 0; ql <= C; ++ql) {
                        i128 lw;
                        int lp;
                        if (b == 2) {
                            const DPEntry &le = tab.d(i, k, ql);
                            if (le.kind == 0) continue;
                            lw = le.work;
                            lp = le.pages;
                        } else {
                            const AuxEntry &le = tab.a(i, b - 1, k, ql);
                            if (!le.valid) continue;
                            lw = le.work;
                            lp = le.pages;
                        }
                        for (int qr = 0; ql + qr <= C; ++qr) {
                            const DPEntry &re = tab.d(k, j, qr);
                            if (re.kind == 0) continue;
                            int q = ql + qr;
                            i128 w = lw + re.work;
                            int pages = lp + re.pages;
                            AuxEntry &ae = tab.a(i, b, j, q);
                            if (better_pair(w, pages, ae.work, ae.pages)) {
                                ae.work = w;
                                ae.pages = pages;
                                ae.split = (uint16_t)k;
                                ae.leftq = (uint8_t)ql;
                                ae.valid = 1;
                            }
                        }
                    }
                }
            }

            const i128 Q = st.q(i, j);
            const i128 T = st.t(i, j);

            // Leaf root option.
            if (span <= 8) {
                for (int mode = 0; mode < 3; ++mode) {
                    if (!mode_legal(starts, i, j, mode)) continue;
                    int P = node_pages(span, 0, mode);
                    int lanes = mode_lanes(mode);
                    i128 kw = (i128)((span + lanes - 1) / lanes + cost.decode[mode]);
                    i128 uncached = (i128)P * cost.miss * T + kw * Q;
                    i128 cached = (i128)P * cost.hit * T + kw * Q;
                    {
                        DPEntry &e = tab.d(i, j, 0);
                        if (better_pair(uncached, P, e.work, e.pages)) {
                            e.work = uncached; e.pages = P; e.kind = 1;
                            e.mode = (uint8_t)mode; e.cached = 0; e.b = 0;
                        }
                    }
                    if (P <= C) {
                        DPEntry &e = tab.d(i, j, P);
                        if (better_pair(cached, P, e.work, e.pages)) {
                            e.work = cached; e.pages = P; e.kind = 1;
                            e.mode = (uint8_t)mode; e.cached = 1; e.b = 0;
                        }
                    }
                }
            }

            // Internal root options.
            for (int b = 2; b <= maxb; ++b) {
                for (int qc = 0; qc <= C; ++qc) {
                    const AuxEntry &ae = tab.a(i, b, j, qc);
                    if (!ae.valid) continue;
                    for (int mode = 0; mode < 3; ++mode) {
                        if (!mode_legal(starts, i, j, mode)) continue;
                        int K = b - 1;
                        int P = node_pages(span, b, mode);
                        int lanes = mode_lanes(mode);
                        i128 kw = (i128)((K + lanes - 1) / lanes + cost.decode[mode]);
                        i128 uncached = (i128)P * cost.miss * T + kw * Q;
                        i128 cached = (i128)P * cost.hit * T + kw * Q;
                        int pages = ae.pages + P;
                        {
                            DPEntry &e = tab.d(i, j, qc);
                            i128 w = ae.work + uncached;
                            if (better_pair(w, pages, e.work, e.pages)) {
                                e.work = w; e.pages = pages; e.kind = 2;
                                e.mode = (uint8_t)mode; e.cached = 0; e.b = (uint8_t)b;
                            }
                        }
                        if (qc + P <= C) {
                            DPEntry &e = tab.d(i, j, qc + P);
                            i128 w = ae.work + cached;
                            if (better_pair(w, pages, e.work, e.pages)) {
                                e.work = w; e.pages = pages; e.kind = 2;
                                e.mode = (uint8_t)mode; e.cached = 1; e.b = (uint8_t)b;
                            }
                        }
                    }
                }
            }
        }
    }
}

// Reconstruct a tree from the selected DP state. Returned vector is BFS ordered.
struct TreeBuilder {
    const OptTables &tab;
    const std::vector<Key> &starts;
    std::vector<Layout> nodes;

    TreeBuilder(const OptTables &t, const std::vector<Key> &s) : tab(t), starts(s) {}

    int build_node(int i, int j, int q) {
        const DPEntry &e = tab.d(i, j, q);
        if (e.kind == 0) throw std::runtime_error("unreachable DP state");
        int id = (int)nodes.size();
        Layout nd;
        nd.lo = i;
        nd.span = j - i;
        nd.mode = e.mode;
        nd.cached = e.cached;
        nodes.push_back(nd);
        if (e.kind == 2) {
            int P = node_pages(nd.span, e.b, e.mode);
            int qc = q - (e.cached ? P : 0);
            std::vector<int> children;
            build_aux(i, e.b, j, qc, children);
            nodes[(size_t)id].children = std::move(children);
        }
        return id;
    }

    void build_aux(int i, int b, int pos, int q, std::vector<int> &out) {
        if (b == 1) {
            out.push_back(build_node(i, pos, q));
            return;
        }
        const AuxEntry &ae = tab.a(i, b, pos, q);
        if (!ae.valid) throw std::runtime_error("unreachable aux state");
        int k = ae.split;
        int ql = ae.leftq;
        int qr = q - ql;
        build_aux(i, b - 1, k, ql, out);
        out.push_back(build_node(k, pos, qr));
    }

    std::vector<Layout> run(int rootq) {
        nodes.clear();
        int root = build_node(0, tab.R, rootq);
        std::vector<Layout> bfs;
        std::vector<int> mp(nodes.size(), -1);
        std::queue<int> qu;
        qu.push(root);
        while (!qu.empty()) {
            int old = qu.front(); qu.pop();
            if (old < 0 || old >= (int)nodes.size() || mp[(size_t)old] != -1)
                throw std::runtime_error("bad reconstructed tree");
            mp[(size_t)old] = (int)bfs.size();
            bfs.push_back(nodes[(size_t)old]);
            for (int c : nodes[(size_t)old].children) qu.push(c);
        }
        if (bfs.size() != nodes.size()) throw std::runtime_error("unreachable reconstructed node");
        for (Layout &nd : bfs)
            for (int &c : nd.children) c = mp[(size_t)c];
        return bfs;
    }
};

// -------------------------------------------------------------- PLAN stage
struct PlanCaseInput {
    int cache_pages = 0;
    CostModel cost;
    int version_count = 0;
    int burst_count = 0;
    std::vector<PlanVersionInput> versions;
    std::vector<PlanBurstInput> bursts;
};

struct CasePlanOutput {
    std::vector<std::vector<uint8_t>> images;
    std::vector<std::vector<TreeAnswer>> burst_answers;
    i128 work = 0;
    long long pages = 0;
};

inline CasePlanOutput solve_case(const PlanCaseInput &in) {
    const int V = in.version_count;
    const int C = in.cache_pages;
    if (V < 1) throw std::runtime_error("no versions");

    std::vector<std::vector<int>> bursts_by_version(V);
    for (int bi = 0; bi < in.burst_count; ++bi) {
        int v = in.bursts[(size_t)bi].version;
        if (v < 0 || v >= V) throw std::runtime_error("burst version");
        bursts_by_version[(size_t)v].push_back(bi);
    }

    std::vector<RunStats> stats;
    stats.reserve(V);
    std::vector<OptTables> tables;
    tables.reserve(V);
    for (int v = 0; v < V; ++v) {
        const auto &vin = in.versions[(size_t)v];
        int R = (int)vin.starts.size();
        if (R < 1 || R > 64) throw std::runtime_error("run count");
        RunStats st = make_run_stats(vin.starts, vin.hops, in.bursts,
                                     bursts_by_version[(size_t)v]);
        stats.push_back(std::move(st));
        tables.emplace_back(R, C);
        optimize_version(tables.back(), vin.starts, vin.hops, in.bursts,
                         bursts_by_version[(size_t)v], in.cost);
    }

    // Joint resident-page knapsack across all versions of this case.
    struct GState { i128 work; int pages; bool valid; };
    std::vector<GState> g((size_t)C + 1), ng((size_t)C + 1);
    for (auto &x : g) x = {INF_WORK, 0, false};
    g[0] = {0, 0, true};
    std::vector<std::vector<int>> alloc((size_t)V, std::vector<int>((size_t)C + 1, -1));

    for (int v = 0; v < V; ++v) {
        for (auto &x : ng) x = {INF_WORK, 0, false};
        const OptTables &tab = tables[(size_t)v];
        const int R = tab.R;
        for (int used = 0; used <= C; ++used) {
            if (!g[(size_t)used].valid) continue;
            for (int q = 0; used + q <= C; ++q) {
                const DPEntry &root = tab.d(0, R, q);
                if (root.kind == 0) continue;
                int np = used + q;
                i128 w = g[(size_t)used].work + root.work;
                int pages = g[(size_t)used].pages + root.pages;
                if (!ng[(size_t)np].valid || better_pair(w, pages, ng[(size_t)np].work, ng[(size_t)np].pages)) {
                    ng[(size_t)np] = {w, pages, true};
                    alloc[(size_t)v][(size_t)np] = q;
                }
            }
        }
        g.swap(ng);
    }

    int bestp = -1;
    for (int p = 0; p <= C; ++p) {
        if (!g[(size_t)p].valid) continue;
        if (bestp < 0 || better_pair(g[(size_t)p].work, g[(size_t)p].pages,
                                     g[(size_t)bestp].work, g[(size_t)bestp].pages))
            bestp = p;
    }
    if (bestp < 0) throw std::runtime_error("no feasible tree");

    std::vector<int> chosen((size_t)V, 0);
    int rem = bestp;
    for (int v = V - 1; v >= 0; --v) {
        int q = alloc[(size_t)v][(size_t)rem];
        if (q < 0) throw std::runtime_error("cache allocation reconstruction");
        chosen[(size_t)v] = q;
        rem -= q;
    }
    if (rem != 0) throw std::runtime_error("cache allocation residual");

    CasePlanOutput out;
    out.images.reserve(V);
    for (int v = 0; v < V; ++v) {
        const auto &vin = in.versions[(size_t)v];
        TreeBuilder tb(tables[(size_t)v], vin.starts);
        std::vector<Layout> tree = tb.run(chosen[(size_t)v]);
        out.images.push_back(build_image_bytes(vin.starts, vin.hops, tree));
    }

    // Recompute the published objective directly from the built layouts.
    i128 total_work = 0;
    long long total_pages = 0;
    int resident = 0;
    for (int v = 0; v < V; ++v) {
        const auto &vin = in.versions[(size_t)v];
        TreeBuilder tb(tables[(size_t)v], vin.starts);
        std::vector<Layout> tree = tb.run(chosen[(size_t)v]);
        for (const Layout &nd : tree) {
            int b = (int)nd.children.size();
            int K = b == 0 ? nd.span : b - 1;
            int P = node_pages(nd.span, b, nd.mode);
            if (nd.cached) resident += P;
            int lanes = mode_lanes(nd.mode);
            i128 key_term = (i128)((K + lanes - 1) / lanes + in.cost.decode[nd.mode]);
            i128 T = stats[(size_t)v].t(nd.lo, nd.lo + nd.span);
            i128 Q = stats[(size_t)v].q(nd.lo, nd.lo + nd.span);
            int rate = nd.cached ? in.cost.hit : in.cost.miss;
            total_work += (i128)P * rate * T + key_term * Q;
        }
        total_pages += (long long)(out.images[(size_t)v].size() / 64);
    }
    if (resident > C) throw std::runtime_error("resident budget violated");
    out.work = total_work;
    out.pages = total_pages;

    out.burst_answers.resize((size_t)in.burst_count);
    for (int bi = 0; bi < in.burst_count; ++bi) {
        const PlanBurstInput &burst = in.bursts[(size_t)bi];
        out.burst_answers[(size_t)bi] =
            trace_image_bytes(out.images[(size_t)burst.version], burst.addresses);
    }
    return out;
}
